function inspectorTabForArtifact(artifactKey) {
    switch(artifactKey){
        case "input_signal":
        case "integration_readiness":
        case "normalized_event":
        case "trigger":
            return "evidence";
        case "decision":
        case "evaluation":
        case "task_trace":
        case "trajectory_score":
        case "verifier_output":
        case "phoenix_spans":
        case "hermes_explanation":
            return "policy";
        case "execution":
        case "goose_review":
        case "hermes_review":
            return "execution";
        case "agent_tasks":
        case "agents":
            return "agents";
        case "feedback":
            return "feedback";
        default:
            return "overview";
    }
}
